f(z) = z[1]^4 - 3z[1]^2 + z[1] + z[2]^2
c(z) = z[1] + z[2]
function solve_from(start)
    model = Model(Ipopt.Optimizer)
    set_silent(model)
    set_attribute(model, "sb", "yes")
    @variable(model, z[i = 1:2], start = start[i])
    @constraint(model, half, z[1] + z[2] >= 0)
    @objective(model, Min, z[1]^4 - 3z[1]^2 + z[1] + z[2]^2)
    optimize!(model)
    return termination_status(model), value.(z), dual(half)
end
for start in ([-2.0, 1.0], [2.0, 0.0])
    status, z, λ = solve_from(start)
