using JuMP, Ipopt
function quiet_model()
    model = Model(Ipopt.Optimizer)
    set_silent(model)
    set_attribute(model, "sb", "yes")
    return model
end
function well(b)
    model = quiet_model()
    @variable(model, x, start = -2.0)
    @variable(model, y, start = 1.0)
    @constraint(model, con, x + y >= b)
    @objective(model, Min, x^4 - 3x^2 + x + y^2)
    optimize!(model)
    return objective_value(model), dual(con)
end
function qp(b)
    model = quiet_model()
    @variable(model, x)
    @variable(model, y)
    @constraint(model, con, x + y == b)
    @objective(model, Min, x^2 + 2y^2)
    optimize!(model)
    return objective_value(model), dual(con)
end
δ = 1e-3
for (name, solve_at) in (("double well", well), ("equality QP", qp))
    b0 = name == "double well" ? 0.0 : 1.0
    _, λ = solve_at(b0)
    fd = (solve_at(b0 + δ)[1] - solve_at(b0 - δ)[1]) / (2δ)
    println(rpad(name, 12), ": dual = ", round(λ; digits = 6), ", central difference = ", round(fd; digits = 6),
            ", agree within 1e-4: ", abs(λ - fd) < 1e-4)
end

