function either_or_max(c, a1, b1, a2, b2, lo, hi)
    model = Model(HiGHS.Optimizer)
    set_silent(model)
    @variable(model, lo[i] <= x[i = 1:length(c)] <= hi[i])
    @constraint(model, a1' * x <= b1)
    @constraint(model, a2' * x <= b2)
    @objective(model, Max, c' * x)
    optimize!(model)
    return objective_value(model)
end

