using JuMP, HiGHS
w = [4.0, 3.0, 6.0, 2.0, 4.5, 3.5]
P = [0 2 -3 0 1 0; 2 0 0 1 0 -2; -3 0 0 2 -4 0; 0 1 2 0 0 1; 1 0 -4 0 0 2; 0 -2 0 1 2 0.0]
n, k = 6, 3
pairs = [(i, j) for i in 1:n for j in i+1:n]
value_of(S) = sum(w[S]; init = 0.0) + sum((P[i, j] for (i, j) in pairs if i in S && j in S); init = 0.0)
best = maximum(value_of(findall(d -> d == '1', reverse(string(m; base = 2, pad = n)))) for m in 0:2^n - 1 if count_ones(m) <= k)
function linearized(full)
    model = Model(HiGHS.Optimizer)
    set_silent(model)
    set_attribute(model, "mip_rel_gap", 0.0)
    @variable(model, y[1:n], Bin)
    @variable(model, 0 <= z[pairs] <= 1)
    @constraint(model, sum(y) <= k)
    for (i, j) in pairs
        @constraint(model, z[(i, j)] <= y[i])
        @constraint(model, z[(i, j)] <= y[j])
        full && @constraint(model, z[(i, j)] >= y[i] + y[j] - 1)
    end
    @objective(model, Max, sum(w .* y) + sum(P[i, j] * z[(i, j)] for (i, j) in pairs))
    optimize!(model)
    return round(objective_value(model); digits = 4), findall(round.(Int, value.(y)) .== 1)
end
println("enumeration: ", best)
println("linearized:  ", linearized(true))
println("without z ≥ y_i + y_j - 1: ", linearized(false))

