function market_price(cost, cap, demand)
    m = Model(HiGHS.Optimizer)
    set_silent(m)
    @variable(m, 0 <= p[g in eachindex(cost)] <= cap[g])
    @constraint(m, balance, sum(p) == demand)
    @objective(m, Min, sum(cost[g] * p[g] for g in eachindex(cost)))
    optimize!(m)
    return objective_value(m) / demand
