using JuMP, HiGHS
cost = [12.0, 25.0, 40.0, 90.0]
cap = [300.0, 200.0, 250.0, 150.0]
function dispatch(D)
    m = Model(HiGHS.Optimizer)
    set_silent(m)
    @variable(m, 0 <= p[g in 1:4] <= cap[g])
    @constraint(m, balance, sum(p) == D)
    @objective(m, Min, sum(cost[g] * p[g] for g in 1:4))
    optimize!(m)
    @assert termination_status(m) == OPTIMAL
    return objective_value(m), dual(balance), shadow_price(balance)
end
for D in (250.0, 600.0, 800.0)
    c, λ, sp = dispatch(D)
    println("D = ", D, ": dual ", λ, ", shadow_price ", sp, ", cost(D + 1) - cost(D) = ", dispatch(D + 1)[1] - c)
end
c, λ, _ = dispatch(500.0)
println("D = 500: left slope ", c - dispatch(499.0)[1], ", right slope ", dispatch(501.0)[1] - c,
        ", dual is one of them: ", λ in (25.0, 40.0))

using JuMP, HiGHS
cost = [12.0, 25.0, 40.0, 90.0]
cap = [300.0, 200.0, 250.0, 150.0]
function two_bus(DA, DB, F)
    m = Model(HiGHS.Optimizer)
    set_silent(m)
    @variable(m, 0 <= p[g in 1:4] <= cap[g])
    @variable(m, f)
    @constraint(m, line, -F <= f <= F)
    @constraint(m, busA, p[1] + p[2] - f == DA)
    @constraint(m, busB, p[3] + p[4] + f == DB)
    @objective(m, Min, sum(cost[g] * p[g] for g in 1:4))
    optimize!(m)
    @assert termination_status(m) == OPTIMAL
    return objective_value(m), value.(p), value(f), dual(busA), dual(busB), dual(line)
end
c, p, f, λA, λB, μ = two_bus(100.0, 450.0, 150.0)
println("schedule ", p, ", line flow ", f)
println("price at A ", λA, " (cost change from 1 MW more at A: ", two_bus(101.0, 450.0, 150.0)[1] - c, ")")
println("price at B ", λB, " (cost change from 1 MW more at B: ", two_bus(100.0, 451.0, 150.0)[1] - c, ")")
println("line limit dual ", μ, " (cost change from 1 MW more capacity: ", two_bus(100.0, 450.0, 151.0)[1] - c, ")")
